import{_ as a,o as t,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"测距器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/modules/range_estimator/index.md","filePath":"v0.3.0-alpha/modules/range_estimator/index.md"}'),r={name:"v0.3.0-alpha/modules/range_estimator/index.md"};function l(n,e,s,c,i,h){return t(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="测距器" tabindex="-1">测距器 <a class="header-anchor" href="#测距器" aria-label="Permalink to &quot;测距器&quot;">​</a></h1><p>适用：v0.3.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>range_estimator</code> · 模块定义版本：1</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>把传播延迟换算为距离。输入 <code>delay_s</code> 以秒计，传播速度以 m/s 计，输出 <code>distance</code> 以米计。单程模型用 <code>distance=v×t</code>；往返模型用 <code>distance=v×t/2</code>。往返的 t 表示从观测端出发、到目标后返回的总传播时间。</p><p>它只执行给定模型的换算，不生成真实传播延迟，也不证明接收信号来自某个目标。传播速度选错、往返含义不一致，即使算式成立也不能得到正确的物理解释。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>相关器.correlation → 峰值检测器.correlation</code>，随后 <code>峰值检测器.delay_s → 测距器.delay_s</code>，捕获测距器的 <code>distance</code> 标量输出。先看中间的 lag 和秒值，再核对米值，方便发现单位或采样率用错的位置。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>delay_s</code>（延迟）</td><td><code>numeric_f64</code></td><td>s；vlen=1</td></tr><tr><td>输出</td><td><code>distance</code>（距离）</td><td><code>numeric_f64</code></td><td>m；vlen=1</td></tr></tbody></table><p>不要把 <code>lag_samples</code> 或 <code>peak_value</code> 接成秒输入：一个是样本数，另一个是相关乘加结果。相关器与峰值检测器必须直接连接，不能用失去 lag 轴的普通向量代替。</p><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p><code>propagation_speed_m_s</code> 应对应正在讲解的传播模型；<code>round_trip</code> 决定 t 是单程还是往返时间。选项需要与输入延迟的物理含义一致，不能只为了得到某个距离数字而切换。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>传播速度 (m/s)<br><code>propagation_speed_m_s</code></td><td><code>299792458</code></td><td>范围 5e-324 至 3.4028234663852886e+38</td><td>重新准备</td></tr><tr><td>往返传播<br><code>round_trip</code></td><td><code>true</code></td><td>按字段类型填写，见下文说明</td><td>重新准备</td></tr></tbody></table><p>默认值和参数范围见上表。教学选值须在案例中显式给出，不能依赖新建实例可能带有的本机默认。</p><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>本模块不提供在线参数修改。停止、修改、重新准备后再运行，分别记录两轮实际执行参数，不能将编辑后的草稿当成旧距离已经使用的参数。</p><h2 id="示例与观察" tabindex="-1">示例与观察 <a class="header-anchor" href="#示例与观察" aria-label="Permalink to &quot;示例与观察&quot;">​</a></h2><h3 id="把延迟换成传播距离" tabindex="-1">把延迟换成传播距离 <a class="header-anchor" href="#把延迟换成传播距离" aria-label="Permalink to &quot;把延迟换成传播距离&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/03-delay-to-distance.cnsproj" download>下载 03-delay-to-distance.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 64 item；重新打开工程后需再次运行以取得数据。</p><p>把延迟换成传播距离</p><ul><li>lag=2 → 0.002 s → 0.34 m，采用 340 m/s 往返传播教学模型；仅把延时改为 3 后为 0.51 m。</li></ul><p><a href="./../../learn/03-delay-to-distance/">延迟换距离</a>使用原始 Fs=1000 sample/s、lag=+2、延迟 0.002 s，显式选择速度 340 m/s 及往返方式，手算结果为 0.34 m。只把源支路延时从 2 改为 3 点后，手算结果为 0.51 m。</p><p>340 m/s 是用于直观换算的声传播教学速度，不是电磁雷达速度，也不是声速精度模型。本例没有真实声学、雷达或 GNSS 采集，不能用 0.34 m 推断硬件测距精度。</p><h2 id="常见问题与失败边界" tabindex="-1">常见问题与失败边界 <a class="header-anchor" href="#常见问题与失败边界" aria-label="Permalink to &quot;常见问题与失败边界&quot;">​</a></h2><p><strong>为什么有时除以 2？</strong> 往返时间涵盖去程和回程。若 t 已经是单程时间，再除以 2 就会把距离算小。本课主对照保持往返方式，单程 0.68 m 只作纸面解释。</p><p><strong>输入负 delay_s 会得到负距离吗？</strong> 负输入延迟使任务失败，错误信息会指出发生位置；不取绝对值、不截成零。先检查 rx/ref 顺序、lag 方向和模型，不把错误变成看似合理的距离。</p><p><strong>零距离是否一定失败？</strong> 不是。来自合法唯一零 lag 的 0 s 可以产生 0 m；零值不充当失败占位。</p><p><strong>相关峰是负值，距离是否要反号？</strong> 不需要按相关值符号改距离。峰值检测保留 signed 峰值，距离使用的是 delay_s；负峰与负延迟不可混为一谈。</p><p><strong>任务失败后是否还能读旧距离？</strong> 可以查看最后有效数据，但必须同时记录任务失败；旧距离不是新测量，也不能把未得到的距离填成零继续画。</p><p><a href="./../correlator/">相关器</a> · <a href="./../peak_detector/">峰值检测器</a> · <a href="./../../learn/">学习路径</a></p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/03-delay-to-distance/">12 延迟换距离</a></li></ul>',35)])])}const _=a(r,[["render",l]]);export{m as __pageData,_ as default};
